mapper.update:
UPDATE iam_user_session_revocations
SET revocation_status = 'RECOVERY_REQUIRED', recovery_exhausted_at = #{now},
    lease_owner = NULL, lease_until = NULL, last_failure = #{failure}
WHERE revocation_status = 'PENDING' AND attempt_count >= #{maximumAttempts}
  AND (lease_until IS NULL OR lease_until <= #{now})

UPDATE iam_refresh_token_families SET revoked_at = GREATEST(#{at}, last_used_at)
WHERE revoked_at IS NULL AND absolute_expires_at > #{at} AND id IN
#{id}

UPDATE iam_user_session_revocations
SET next_attempt_at = #{retryAt}, lease_owner = NULL, lease_until = NULL, last_failure = #{failure}
WHERE revocation_request_id = #{requestId} AND revocation_status = 'PENDING'
  AND fencing_token = #{fencingToken}

UPDATE iam_user_session_revocations
SET revocation_status = 'RECOVERY_REQUIRED', recovery_exhausted_at = #{at},
    lease_owner = NULL, lease_until = NULL, last_failure = #{failure}
WHERE revocation_request_id = #{requestId} AND revocation_status = 'PENDING'
  AND fencing_token = #{fencingToken}
